    public TaskEvent() {}

    public TaskEvent(long timestampMicros, long jobId, int taskIndex, long machineId, int eventType) {
        this.timestampMicros = timestampMicros;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
    }

    public long getTimestampMicros() {
        return timestampMicros;
    }

    public long getTimestampMillis() {
        return timestampMicros / 1000L;
    }

    public long getJobId() {
        return jobId;
    }

    public int getTaskIndex() {
        return taskIndex;
    }

    public long getMachineId() {
        return machineId;
    }

    public int getEventType() {
        return eventType;
    }

    public boolean isSubmit() {
        return eventType == EVENT_SUBMIT;
    }

    public static TaskEvent fromCsvLine(String line) {
        if (line == null) {
            return null;
        }
        String trimmed = line.trim();
        if (trimmed.isEmpty()) {
            return null;
        }

        // task_events schema (v2.1):
        // 0 time, 1 missing info, 2 job id, 3 task index, 4 machine id, 5 event type, ...
        String[] p = trimmed.split(",", -1);
        if (p.length < 6) {
            return null;
        }

        long ts = parseLong(p[0], -1L);
        long jobId = parseLong(p[2], -1L);
        int taskIndex = (int) parseLong(p[3], -1L);
        long machineId = parseLong(p[4], -1L);
        int eventType = (int) parseLong(p[5], -1L);
        if (ts < 0 || jobId < 0 || eventType < 0) {
            return null;
        }
        return new TaskEvent(ts, jobId, taskIndex, machineId, eventType);
    }

    private static long parseLong(String s, long defaultVal) {
        if (s == null || s.isEmpty()) {
            return defaultVal;
        }
        try {
            return Long.parseLong(s);
        } catch (NumberFormatException e) {
            return defaultVal;
        }
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestampMicros=" + timestampMicros +
                ", jobId=" + jobId +
                ", taskIndex=" + taskIndex +
                ", machineId=" + machineId +
                ", eventType=" + eventType +
                '}';
    }
}
