import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.common.typeinfo.TypeHint;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.ConnectedStreams;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.BufferedReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.Set;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    private static final Set<Integer> JOB_TERMINAL_EVENT_TYPES = new HashSet<>();

    static {
        // In the Google cluster traces, terminal job events are FINISH (4), KILL (5), and FAIL (3).
        JOB_TERMINAL_EVENT_TYPES.add(3);
        JOB_TERMINAL_EVENT_TYPES.add(4);
        JOB_TERMINAL_EVENT_TYPES.add(5);
    }

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssize = params.getInt("sesssize", 600);

        if (taskInput == null || jobInput == null || outputPath == null) {
            throw new IllegalArgumentException("Required parameters: --task_input, --job_input, --output");
        }

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<TaskEvent> taskEventsStream = env
                .addSource(taskSourceOrTest(new TaskEventFileSource(taskInput)),
                        TypeInformation.of(new TypeHint<TaskEvent>() {}));

        DataStream<TaskEvent> submitEvents = taskEventsStream
                .filter(TaskEvent::isSubmit);

        DataStream<JobStageCount> stageCounts = submitEvents
                .keyBy(TaskEvent::getJobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .aggregate(new CountAgg(), new ToStageCount());

        DataStream<JobEvent> jobEventsStream = env
                .addSource(jobSourceOrTest(new JobEventFileSource(jobInput)),
                        TypeInformation.of(new TypeHint<JobEvent>() {}));

        DataStream<JobFinished> finishedJobs = jobEventsStream
                .filter(e -> JOB_TERMINAL_EVENT_TYPES.contains(e.getEventType()))
                .map(e -> new JobFinished(e.getJobId(), e.getTimestampMillis()))
                .returns(TypeInformation.of(new TypeHint<JobFinished>() {}));

        ConnectedStreams<JobStageCount, JobFinished> connected = stageCounts
                .keyBy(JobStageCount::getJobId)
                .connect(finishedJobs.keyBy(JobFinished::getJobId));

        DataStream<String> results = connected
                .process(new EmitMaxStageOnEnd());

        results
                .addSink((org.apache.flink.streaming.api.functions.sink.SinkFunction<String>) sinkOrTest(new LocalTextFileSink(outputPath)))
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    public static class JobStageCount {
        private long jobId;
        private int count;

        public JobStageCount() {}

        public JobStageCount(long jobId, int count) {
            this.jobId = jobId;
            this.count = count;
        }

        public long getJobId() {
            return jobId;
        }

        public int getCount() {
            return count;
        }
    }

    public static class JobFinished {
        private long jobId;
        private long timestampMillis;

        public JobFinished() {}

        public JobFinished(long jobId, long timestampMillis) {
            this.jobId = jobId;
            this.timestampMillis = timestampMillis;
        }

        public long getJobId() {
            return jobId;
        }

        public long getTimestampMillis() {
            return timestampMillis;
        }
    }

    public static class CountAgg implements AggregateFunction<TaskEvent, Long, Long> {
        @Override
        public Long createAccumulator() {
            return 0L;
        }

        @Override
        public Long add(TaskEvent value, Long accumulator) {
            return accumulator + 1L;
        }

        @Override
        public Long getResult(Long accumulator) {
            return accumulator;
        }

        @Override
        public Long merge(Long a, Long b) {
            return a + b;
        }
    }

    public static class ToStageCount extends ProcessWindowFunction<Long, JobStageCount, Long, TimeWindow> {
        @Override
        public void process(Long jobId, Context context, Iterable<Long> elements, Collector<JobStageCount> out) {
            long c = elements.iterator().next();
            out.collect(new JobStageCount(jobId, (int) c));
        }
    }

    public static class EmitMaxStageOnEnd extends KeyedCoProcessFunction<Long, JobStageCount, JobFinished, String> {

        private transient ValueState<Integer> maxStage;
        private transient ValueState<Boolean> finished;
        private transient ValueState<Boolean> timerRegistered;

        @Override
        public void open(Configuration parameters) {
            maxStage = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStage", Integer.class));
            finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Boolean.class));
            timerRegistered = getRuntimeContext().getState(new ValueStateDescriptor<>("timerRegistered", Boolean.class));
        }

        @Override
        public void processElement1(JobStageCount value, Context ctx, Collector<String> out) throws Exception {
            Integer current = maxStage.value();
            if (current == null || value.getCount() > current) {
                maxStage.update(value.getCount());
            }
        }

        @Override
        public void processElement2(JobFinished value, Context ctx, Collector<String> out) throws Exception {
            finished.update(true);
            Boolean registered = timerRegistered.value();
            if (registered == null || !registered) {
                // Emit exactly once per finished job, after all inputs have been fully consumed.
                ctx.timerService().registerEventTimeTimer(Long.MAX_VALUE - 1);
                timerRegistered.update(true);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<String> out) throws Exception {
            Boolean isFinished = finished.value();
            if (isFinished != null && isFinished) {
                Integer m = maxStage.value();
                int result = (m == null) ? 0 : m;
                out.collect("(" + ctx.getCurrentKey() + "," + result + ")");
            }
            maxStage.clear();
            finished.clear();
            timerRegistered.clear();
        }
    }

    public static class TaskEventFileSource implements SourceFunction<TaskEvent> {

        private final String path;
        private volatile boolean running = true;

        public TaskEventFileSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(openPossiblyGz(path), StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    TaskEvent ev = TaskEvent.fromCsvLine(line);
                    if (ev == null) {
                        continue;
                    }
                    synchronized (ctx.getCheckpointLock()) {
                        ctx.collectWithTimestamp(ev, ev.getTimestampMillis());
                    }
                }

                synchronized (ctx.getCheckpointLock()) {
                    ctx.emitWatermark(org.apache.flink.streaming.api.watermark.Watermark.MAX_WATERMARK);
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    public static class JobEventFileSource implements SourceFunction<JobEvent> {

        private final String path;
        private volatile boolean running = true;

        public JobEventFileSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(openPossiblyGz(path), StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    JobEvent ev = JobEvent.fromCsvLine(line);
                    if (ev == null) {
                        continue;
                    }
                    synchronized (ctx.getCheckpointLock()) {
                        ctx.collectWithTimestamp(ev, ev.getTimestampMillis());
                    }
                }

                synchronized (ctx.getCheckpointLock()) {
                    ctx.emitWatermark(org.apache.flink.streaming.api.watermark.Watermark.MAX_WATERMARK);
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static InputStream openPossiblyGz(String path) throws IOException {
        InputStream in = Files.newInputStream(Paths.get(path));
        if (path.endsWith(".gz")) {
            return new GZIPInputStream(in);
        }
        return in;
    }

    public static class LocalTextFileSink extends RichSinkFunction<String> {

        private final String path;
        private transient BufferedWriter writer;

        public LocalTextFileSink(String path) {
            this.path = path;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            super.open(parameters);
            // single-parallelism sink: one writer, overwrite output file
            writer = new BufferedWriter(new FileWriter(path, false));
        }

        @Override
        public synchronized void invoke(String value, Context context) throws Exception {
            writer.write(value);
            writer.newLine();
        }

        @Override
        public void close() throws Exception {
            try {
                if (writer != null) {
                    writer.flush();
                    writer.close();
                }
            } finally {
                super.close();
            }
        }
    }
}
