                    ctx.emitWatermark(org.apache.flink.streaming.api.watermark.Watermark.MAX_WATERMARK);
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static InputStream openPossiblyGz(String path) throws IOException {
        InputStream in = Files.newInputStream(Paths.get(path));
        if (path.endsWith(".gz")) {
            return new GZIPInputStream(in);
        }
        return in;
    }

    public static class LocalTextFileSink extends RichSinkFunction<String> {

        private final String path;
        private transient BufferedWriter writer;

        public LocalTextFileSink(String path) {
            this.path = path;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            super.open(parameters);
            // single-parallelism sink: one writer, overwrite output file
            writer = new BufferedWriter(new FileWriter(path, false));
        }

        @Override
        public synchronized void invoke(String value, Context context) throws Exception {
            writer.write(value);
            writer.newLine();
        }

        @Override
        public void close() throws Exception {
            try {
                if (writer != null) {
                    writer.flush();
                    writer.close();
                }
            } finally {
                super.close();
            }
        }
    }
}
