        return "TaskEvent{" +
                "timestampMicros=" + timestampMicros +
                ", jobId=" + jobId +
                ", taskIndex=" + taskIndex +
                ", machineId=" + machineId +
                ", eventType=" + eventType +
                '}';
    }
}
